{
  "root_causes": [
    {
      "service": "ts-train-service",
      "fault_kind": "database_call_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, count(*) n, round(avg(duration)/1e6,1) avg_ms, round(max(duration)/1e6,1) max_ms FROM abnormal_traces WHERE service_name='ts-train-service' AND span_name LIKE 'SELECT%' GROUP BY 1,2 ORDER BY 4 DESC",
          "claim": "In the incident, train-service's own SELECT database spans average 1.7–2.5 s, with maxima above 120 s."
        },
        {
          "kind": "trace",
          "sql": "SELECT 'normal' p, span_name, count(*) n, round(avg(duration)/1e6,1) avg_ms FROM normal_traces WHERE service_name='ts-train-service' AND span_name LIKE 'SELECT%' GROUP BY 1,2 UNION ALL SELECT 'abnormal', span_name, count(*), round(avg(duration)/1e6,1) FROM abnormal_traces WHERE service_name='ts-train-service' AND span_name LIKE 'SELECT%' GROUP BY 1,2 ORDER BY 2,1",
          "claim": "Normal-period train-service SELECT spans average about 1–2 ms; during the incident they are over 1000x slower."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, round(avg(duration)/1e6,1) avg_ms FROM abnormal_traces WHERE service_name='ts-train-service' AND span_name IN ('Transaction.commit','TrainController.query') GROUP BY 1,2",
          "claim": "Transaction.commit and TrainController.query time is almost entirely spent in the slow database calls."
        },
        {
          "kind": "metric",
          "sql": "SELECT metric, round(avg(value),3) avg_v FROM abnormal_metrics WHERE service_name='ts-train-service' AND metric IN ('container.cpu.usage','container.memory.working_set') GROUP BY 1",
          "claim": "train-service container CPU and memory stay at or below normal levels, so this is not resource saturation."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-train-service",
      "to": "ts-basic-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name parent_svc, c.service_name child_svc, count(*) n, round(avg(c.duration)/1e6,1) child_ms, round(avg(p.duration)/1e6,1) parent_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND p.service_name='ts-basic-service' AND c.service_name='ts-train-service' GROUP BY ALL",
          "claim": "basic-service calls to train-service take about 1.9 s on average, matching train-service's slow server spans."
        }
      ]
    },
    {
      "from": "ts-basic-service",
      "to": "ts-travel-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name parent_svc, c.service_name child_svc, count(*) n, round(avg(c.duration)/1e6,1) child_ms, round(avg(p.duration)/1e6,1) parent_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND p.service_name='ts-travel-service' AND c.service_name='ts-basic-service' GROUP BY ALL",
          "claim": "travel-service calls to basic-service take about 2.8 s on average, inheriting basic's slowness."
        }
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name parent_svc, c.service_name child_svc, count(*) n, round(avg(c.duration)/1e6,1) child_ms, round(avg(p.duration)/1e6,1) parent_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND p.service_name='ts-route-plan-service' AND c.service_name='ts-travel-service' GROUP BY ALL",
          "claim": "route-plan-service calls to travel-service take about 0.9 s on average during the incident."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name parent_svc, c.service_name child_svc, count(*) n, round(avg(c.duration)/1e6,1) child_ms, round(avg(p.duration)/1e6,1) parent_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND p.service_name='ts-travel-plan-service' AND c.service_name='ts-route-plan-service' GROUP BY ALL",
          "claim": "travel-plan-service calls to route-plan-service average about 4.2 s during the incident."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name parent_svc, c.service_name child_svc, count(*) n, round(avg(c.duration)/1e6,1) child_ms, round(avg(p.duration)/1e6,1) parent_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND p.service_name='ts-ui-dashboard' AND c.service_name='ts-travel-plan-service' GROUP BY ALL",
          "claim": "ui-dashboard calls to travel-plan-service average about 13 s during the incident, the user-facing travelPlan requests slow down."
        }
      ]
    }
  ]
}
